def generate_spaces(s):
    n = len(s)
    if n == 0:
        print("")
        return
    total = 1 << (n - 1)
    result = []
    for mask in range(total):
        current = s[0]
        for i in range(1, n):
            if mask & (1 << (i - 1)):
                current += " " + s[i]
            else:
                current += s[i]
        result.append(current)
    result.sort()
    for r in result:
        print(r)

if __name__ == "__main__":
    s = input().strip()
    generate_spaces(s)
